<template>
  <div class="commercial-page">
    <section class="commercial-hero billing-hero"><div><span class="eyebrow">PLAN & USAGE</span><h2>套餐、用量与账单</h2><p>支付结果只采用服务端订单状态；页面跳转不会改变订阅和额度。</p></div><div class="commercial-stats"><span><strong>{{ currentPlan?.planName??'未订阅' }}</strong><small>当前套餐</small></span><span><strong>{{ subscription?daysRemaining(subscription.periodEnd):'—' }}</strong><small>剩余天数</small></span><span><strong>{{ money(usage?.amountMinorUnits??0,usage?.currency??'CNY') }}</strong><small>AI 用量成本</small></span></div></section>
    <UnifiedState v-if="loading" state="loading" description="正在读取服务端套餐、额度和订单状态。" />
    <UnifiedState v-else-if="error" state="error" :description="error" retryable @retry="load" />
    <template v-else>
      <el-alert v-if="subscription && daysRemaining(subscription.periodEnd)<=7" type="warning" :title="`当前订阅将在 ${formatDate(subscription.periodEnd)} 到期，请提前确认续费安排。`" show-icon :closable="false" />
      <section class="commercial-card"><header><div><span class="eyebrow">PLAN COMPARISON</span><h3>套餐对比</h3></div><el-tag v-if="subscription" :type="subscription.status==='ACTIVE'?'success':'warning'">{{subscription.status}}</el-tag></header><div class="plan-comparison-grid"><article v-for="plan in plans" :key="plan.id" :class="{current:plan.id===subscription?.planVersionId}"><header><div><strong>{{plan.planName}}</strong><small>{{plan.planCode}} · V{{plan.version}}</small></div><el-tag v-if="plan.id===subscription?.planVersionId" type="success">当前套餐</el-tag></header><p class="plan-price"><strong>{{money(plan.priceMinorUnits,plan.currency)}}</strong><span>/ {{periodLabel(plan.billingPeriod)}}</span></p><ul><li v-for="(limit,code) in plan.quotas" :key="code"><span>{{quotaLabel(String(code))}}</span><strong>{{formatNumber(limit)}}</strong></li></ul><el-button :type="plan.id===subscription?.planVersionId?'default':'primary'" :disabled="plan.id===subscription?.planVersionId||!app.currentMember?.owner" @click="choosePlan(plan)">{{plan.id===subscription?.planVersionId?'正在使用':app.currentMember?.owner?'选择套餐':'仅企业所有者可变更'}}</el-button></article></div><UnifiedState v-if="!plans.length" state="empty" title="暂无可售套餐" description="平台尚未发布有效套餐版本。" /></section>
      <section class="commercial-card"><header><div><span class="eyebrow">QUOTA HEALTH</span><h3>当前额度与使用量</h3></div><span class="commercial-hint">已用量与预留量均计入占用</span></header><div class="quota-grid"><article v-for="quota in quotas" :key="quota.quotaCode"><header><strong>{{quotaLabel(quota.quotaCode)}}</strong><span>{{quota.used}} 已用 · {{quota.reserved}} 预留</span></header><el-progress :percentage="quotaPercent(quota)" :status="quotaPercent(quota)>=90?'exception':quotaPercent(quota)>=75?'warning':undefined" /><footer><span>剩余 {{quota.remaining}}</span><small>{{formatDate(quota.windowEnd)}} 重置</small></footer></article></div><UnifiedState v-if="!quotas.length" state="empty" title="暂无额度" description="当前企业尚未开通可计量资源。" /></section>
      <section class="commercial-card"><header><div><span class="eyebrow">SERVER-CONFIRMED ORDERS</span><h3>订单与历史账单</h3></div><el-button :loading="refreshingOrders" @click="refreshOrders">刷新服务端状态</el-button></header><el-alert type="info" title="只有订单同时为 PAID 且服务端返回 paidAt 时，页面才显示支付成功。" :closable="false" show-icon /><el-table :data="orders" stripe empty-text="暂无订单" style="margin-top:14px"><el-table-column prop="orderNo" label="订单号" min-width="190" /><el-table-column label="套餐" min-width="150"><template #default="{row}">{{planName(row.planVersionId)}}</template></el-table-column><el-table-column label="金额" width="130"><template #default="{row}">{{money(row.amountMinorUnits,row.currency)}}</template></el-table-column><el-table-column label="支付状态" min-width="210"><template #default="{row}"><el-tag :type="paymentStatus(row).type">{{paymentStatus(row).label}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="170"><template #default="{row}">{{formatDateTime(row.createdAt)}}</template></el-table-column><el-table-column prop="paidAt" label="服务端确认时间" min-width="180"><template #default="{row}">{{row.paidAt?formatDateTime(row.paidAt):'—'}}</template></el-table-column></el-table></section>
    </template>
    <CommonDialog v-model="orderOpen" title="确认套餐订单" width="500px"><template v-if="selectedPlan"><div class="order-confirm"><span>目标套餐</span><strong>{{selectedPlan.planName}}</strong><span>订单金额</span><strong>{{money(selectedPlan.priceMinorUnits,selectedPlan.currency)}}</strong></div><el-alert type="warning" title="创建订单不会立即显示支付成功；需等待支付服务端签名回调确认。" :closable="false" show-icon /></template><template #footer><el-button @click="orderOpen=false">取消</el-button><el-button type="primary" :loading="ordering" @click="createOrder">创建订单</el-button></template></CommonDialog>
  </div>
</template>

<script setup lang="ts">
import type { Id } from '../api/resource-id'
import { computed, onBeforeUnmount, ref, watch } from 'vue'; import { ElMessage } from 'element-plus'; import CommonDialog from '../components/common/CommonDialog.vue'; import UnifiedState from '../components/common/UnifiedState.vue'; import { commercialApi } from '../api/runtime'; import { paymentStatus, quotaPercent } from '../commercial/presentation'; import type { Order, PlanVersion, QuotaBalance, Subscription, UsageSummary } from '../commercial/types'; import { useAppStore } from '../stores/app'
const app=useAppStore(); const plans=ref<PlanVersion[]>([]); const subscription=ref<Subscription>(); const orders=ref<Order[]>([]); const quotas=ref<QuotaBalance[]>([]); const usage=ref<UsageSummary>(); const loading=ref(true); const error=ref(''); const refreshingOrders=ref(false); const orderOpen=ref(false); const selectedPlan=ref<PlanVersion>(); const ordering=ref(false); let pollTimer:ReturnType<typeof setTimeout>|undefined
const currentPlan=computed(()=>plans.value.find(item=>item.id===subscription.value?.planVersionId))
async function load(){loading.value=true;error.value='';const results=await Promise.allSettled([commercialApi.plans(),commercialApi.subscription(),commercialApi.orders(),commercialApi.quotas(),commercialApi.usage()]);if(results[0].status==='fulfilled')plans.value=results[0].value;if(results[1].status==='fulfilled')subscription.value=results[1].value;if(results[2].status==='fulfilled')orders.value=results[2].value;if(results[3].status==='fulfilled')quotas.value=results[3].value;if(results[4].status==='fulfilled')usage.value=results[4].value;const required=[results[0],results[2],results[3],results[4]].find(item=>item.status==='rejected') as PromiseRejectedResult|undefined;if(required)error.value=required.reason instanceof Error?required.reason.message:'商业化数据加载失败';loading.value=false;schedulePoll()}
function choosePlan(plan:PlanVersion){selectedPlan.value=plan;orderOpen.value=true} async function createOrder(){if(!selectedPlan.value)return;ordering.value=true;try{const order=await commercialApi.createOrder(selectedPlan.value.id);orders.value.unshift(order);orderOpen.value=false;schedulePoll();ElMessage.success('订单已创建，等待服务端支付确认')}finally{ordering.value=false}}
function schedulePoll(){if(pollTimer)clearTimeout(pollTimer);if(!orders.value.some(item=>!paymentStatus(item).confirmed&&!['FAILED','CANCELLED','REFUNDED'].includes(item.status)))return;pollTimer=setTimeout(()=>void refreshOrders(),3000)}
async function refreshOrders(){refreshingOrders.value=true;try{orders.value=await commercialApi.orders();const current=await commercialApi.subscription().catch(()=>undefined);if(current)subscription.value=current;schedulePoll()}finally{refreshingOrders.value=false}}
function money(value:number,currency:string){return new Intl.NumberFormat('zh-CN',{style:'currency',currency}).format(value/100)} function formatNumber(value:number){return new Intl.NumberFormat('zh-CN').format(value)} function daysRemaining(value:string){return Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/86400000))} function formatDate(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(value))} function formatDateTime(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))} function planName(id:Id){return plans.value.find(item=>item.id===id)?.planName??`套餐 ${id}`} function periodLabel(v:string){return v==='YEAR'?'年':'月'} function quotaLabel(v:string){return({AI_REQUEST:'AI 分析次数',TOKEN:'模型 Token',EXPORT:'报告导出',MEMBER:'企业成员',DATASET:'数据集'} as Record<string,string>)[v]??v}
watch(()=>app.contextVersion,()=>void load());onBeforeUnmount(()=>{if(pollTimer)clearTimeout(pollTimer)});void load()
</script>
